37: 		// Determine the event name early for fail-open handling.
38: 		eventName := ""
39: 		if len(args) >= 2 {
40: 			eventName = args[1]
41: 		} else if len(args) == 1 {
42: 			eventName = args[0]
43: 		}
44: 		isPreToolUse := strings.EqualFold(eventName, "PreToolUse") || strings.EqualFold(eventName, "pre_tool_use")
45: 
46: 		// FAIL-OPEN: For PreToolUse, any panic or error must result in
47: 		// {"decision":"allow"} on stdout and exit 0. A non-zero exit or
48: 		// empty/invalid output causes an implicit deny that blocks ALL
49: 		// tool calls across the entire machine.
50: 		if isPreToolUse {
51: 			defer func() {
52: 				if r := recover(); r != nil {
53: 					fmt.Fprintln(cmd.OutOrStdout(), `{"decision":"allow","reason":"fail-open: panic recovery"}`)
54: 				}
55: 			}()
56: 		}
57: 
58: 		// Fast path for non-enrolled repositories / kill switch (target <= 5ms)
59: 		var payload []byte
60: 		if !hookProbeFlag {
61: 			if os.Getenv("REPO_MEMORY_DISABLED") == "1" {
62: 				if isPreToolUse {
