66: 				}
67: 				return nil
68: 			}
69: 
70: 			targetDir := hookWorkspaceFlag
71: 			if targetDir == "" {
72: 				payload, _ = io.ReadAll(cmd.InOrStdin())
73: 				type fastPayload struct {
74: 					WorkspacePaths      []string `json:"workspacePaths"`
75: 					WorkspacePathsSnake []string `json:"workspace_paths"`
76: 				}
77: 				var parsed fastPayload
78: 				if len(payload) > 0 {
79: 					_ = json.Unmarshal(payload, &parsed)
80: 				}
81: 				if len(parsed.WorkspacePaths) > 0 && parsed.WorkspacePaths[0] != "" {
82: 					targetDir = parsed.WorkspacePaths[0]
83: 				} else if len(parsed.WorkspacePathsSnake) > 0 && parsed.WorkspacePathsSnake[0] != "" {
