111: func hookRunE(cmd *cobra.Command, args []string, eventName string, isPreToolUse bool, preReadPayload []byte) error {
112: 	if hookProbeFlag {
113: 		event := "unknown"
114: 		if len(args) >= 2 {
115: 			event = args[1]
116: 		} else if len(args) == 1 {
117: 			if strings.EqualFold(args[0], "antigravity") || strings.EqualFold(args[0], "claudecode") || strings.EqualFold(args[0], "fake") {
118: 				event = "unknown"
119: 			} else {
120: 				event = args[0]
121: 			}
122: 		}
123: 
124: 		payload := preReadPayload
125: 		if len(payload) == 0 {
126: 			var err error
127: 			payload, err = io.ReadAll(cmd.InOrStdin())
128: 			if err != nil {
129: 				return fmt.Errorf("reading hook payload: %w", err)
130: 			}
131: 		}
132: 
133: 		out, err := handleProbe(event, payload)
134: 		if err != nil {
135: 			return err
136: 		}
137: 		fmt.Fprintln(cmd.OutOrStdout(), string(out))
138: 		return nil
139: 	}
140: 
141: 	harnessName := ""
142: 	if len(args) >= 2 {
143: 		harnessName = args[0]
144: 	}
145: 
146: 	if (strings.EqualFold(harnessName, "antigravity") || harnessName == "") && strings.EqualFold(eventName, "stop") {
147: 		payload := preReadPayload
148: 		if len(payload) == 0 {
149: 			var err error
150: 			payload, err = io.ReadAll(cmd.InOrStdin())
151: 			if err != nil {
152: 				return fmt.Errorf("reading hook payload: %w", err)
153: 			}
154: 		}
155: 
156: 		out, err := antigravity.HandleStop(cmd.Context(), payload, antigravity.WithWorkspace(hookWorkspaceFlag))
157: 		if err != nil {
158: 			return err
159: 		}
160: 		fmt.Fprintln(cmd.OutOrStdout(), string(out))
161: 		return nil
162: 	}
163: 
164: 	valid, err := harness.FastPathValidation(hookWorkspaceFlag, "")
165: 	if err != nil || !valid {
166: 		// Sub-5ms fast-path: immediately return harness no-op output
167: 		if isPreToolUse {
168: 			fmt.Fprintln(cmd.OutOrStdout(), `{"decision":"allow"}`)
169: 		} else {
170: 			fmt.Fprintln(cmd.OutOrStdout(), "{}")
171: 		}
172: 		return nil
173: 	}
174: 
175: 	if len(args) >= 2 {
176: 		fmt.Fprintf(cmd.OutOrStdout(), "hook subcommand stub: harness=%s event=%s\n", args[0], args[1])
177: 	} else {
178: 		fmt.Fprintln(cmd.OutOrStdout(), "hook subcommand stub")
179: 	}
180: 	return nil
181: }
