189: func handleProbe(event string, payload []byte) ([]byte, error) {
190: 	decision := strings.ToLower(strings.TrimSpace(hookProbeDecisionFlag))
191: 	if decision == "" {
192: 		decision = "allow"
193: 	}
194: 	switch decision {
195: 	case "allow", "deny", "ask":
196: 	default:
197: 		return nil, fmt.Errorf("invalid --probe-decision: %q (must be allow, deny, or ask)", hookProbeDecisionFlag)
198: 	}
199: 
200: 	type probePayload struct {
201: 		TranscriptPath      string   `json:"transcriptPath"`
202: 		TranscriptPathSnake string   `json:"transcript_path"`
203: 		WorkspacePaths      []string `json:"workspacePaths"`
204: 		WorkspacePathsSnake []string `json:"workspace_paths"`
205: 		RepoID              string   `json:"repo_id"`
206: 		RepoIDAlt           string   `json:"repoId"`
207: 	}
208: 
209: 	var parsed probePayload
210: 	if len(payload) > 0 {
211: 		_ = json.Unmarshal(payload, &parsed)
212: 	}
213: 	if parsed.TranscriptPath == "" && parsed.TranscriptPathSnake != "" {
214: 		parsed.TranscriptPath = parsed.TranscriptPathSnake
215: 	}
216: 	if len(parsed.WorkspacePaths) == 0 && len(parsed.WorkspacePathsSnake) > 0 {
217: 		parsed.WorkspacePaths = parsed.WorkspacePathsSnake
218: 	}
219: 	if parsed.RepoID == "" && parsed.RepoIDAlt != "" {
220: 		parsed.RepoID = parsed.RepoIDAlt
221: 	}
222: 
223: 	dataDir := config.DataDir()
224: 
225: 	repoID := parsed.RepoID
226: 	if repoID == "" {
227: 		candidate := hookWorkspaceFlag
228: 		if candidate == "" && len(parsed.WorkspacePaths) > 0 && parsed.WorkspacePaths[0] != "" {
229: 			candidate = parsed.WorkspacePaths[0]
230: 		}
231: 		if candidate == "" && parsed.TranscriptPath != "" {
232: 			if root, err := gitops.FindRepoRoot(filepath.Dir(parsed.TranscriptPath)); err == nil {
233: 				candidate = root
234: 			}
235: 		}
236: 		if candidate == "" {
237: 			candidate, _ = os.Getwd()
238: 		}
239: 
240: 		if entry, found, _ := config.FindRegistryEntry(dataDir, candidate); found && entry != nil && entry.RepoID != "" {
241: 			repoID = entry.RepoID
242: 		}
243: 
244: 		if repoID == "" && candidate != "" {
245: 			if root, err := gitops.FindRepoRoot(candidate); err == nil && root != "" {
246: 				if id, err := gitops.GenerateRepoID(root); err == nil && id != "" {
247: 					repoID = id
248: 				}
249: 			}
250: 			if repoID == "" {
251: 				if id, err := gitops.GenerateRepoID(candidate); err == nil && id != "" {
252: 					repoID = id
253: 				}
254: 			}
255: 		}
256: 
257: 		if repoID == "" {
258: 			repoID = "unknown"
259: 		}
260: 	}
261: 
262: 	logsDir := filepath.Join(dataDir, repoID, "logs")
263: 	if err := os.MkdirAll(logsDir, 0755); err != nil {
264: 		return nil, fmt.Errorf("creating probe logs directory %s: %w", logsDir, err)
265: 	}
266: 
267: 	timestamp := probeTimeNow().UTC().Format("20060102T150405.000000000Z")
268: 
269: 	probeFile := filepath.Join(logsDir, fmt.Sprintf("probe_%s_%s.json", event, timestamp))
270: 	rawPayload := payload
271: 	if len(bytes.TrimSpace(rawPayload)) == 0 {
272: 		rawPayload = []byte("{}")
273: 	}
274: 	if err := os.WriteFile(probeFile, rawPayload, 0644); err != nil {
275: 		return nil, fmt.Errorf("writing probe log %s: %w", probeFile, err)
276: 	}
277: 
278: 	if parsed.TranscriptPath != "" {
279: 		targetPath := parsed.TranscriptPath
280: 		if targetPath == "~" {
281: 			if home, err := os.UserHomeDir(); err == nil {
282: 				targetPath = home
283: 			}
284: 		} else if strings.HasPrefix(targetPath, "~/") {
285: 			if home, err := os.UserHomeDir(); err == nil {
286: 				targetPath = filepath.Join(home, targetPath[2:])
287: 			}
288: 		}
289: 		if !filepath.IsAbs(targetPath) {
290: 			if hookWorkspaceFlag != "" {
291: 				targetPath = filepath.Join(hookWorkspaceFlag, targetPath)
292: 			} else if len(parsed.WorkspacePaths) > 0 && parsed.WorkspacePaths[0] != "" {
293: 				targetPath = filepath.Join(parsed.WorkspacePaths[0], targetPath)
294: 			}
295: 		}
296: 		if fi, err := os.Stat(targetPath); err == nil && !fi.IsDir() {
297: 			if data, err := os.ReadFile(targetPath); err == nil {
298: 				snapshotFile := filepath.Join(logsDir, fmt.Sprintf("probe_%s_%s_transcript.jsonl", event, timestamp))
299: 				_ = os.WriteFile(snapshotFile, data, 0644)
300: 				_ = config.RotateLogFile(snapshotFile, config.DefaultMaxLogBytes, config.DefaultMaxRotatedFiles)
301: 			}
302: 		}
303: 	}
304: 
305: 	// Clean up probe logs older than 7 days
306: 	_, _ = config.CleanProbeLogs(logsDir, 7*24*time.Hour)
307: 
308: 	if strings.EqualFold(event, "PreToolUse") || strings.EqualFold(event, "pre_tool_use") {
309: 		resp := map[string]string{
310: 			"decision": decision,
311: 			"reason":   "probe " + decision,
312: 		}
313: 		return json.Marshal(resp)
314: 	}
315: 
316: 	return []byte("{}"), nil
317: }
